   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <main id="main-content">
       <div id="app"></div>
     </main>

     <script>
       const requiredLabel = '<span class="required-marker" aria-hidden="true">*</span>';

       function FormField({ id, label, type, name, required = false, autocomplete, helperText, inputMode }) {
         const describedBy = helperText ? `${id}-help` : "";

         return `
           <div class="form-field">
             <label for="${id}">${label}${required ? ` ${requiredLabel}` : ""}</label>
             <input
               id="${id}"
               name="${name}"
               type="${type}"
               ${required ? "required" : ""}
               ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
               ${inputMode ? `inputmode="${inputMode}"` : ""}
               ${describedBy ? `aria-describedby="${describedBy}"` : ""}
             >
             ${helperText ? `<p class="helper-text" id="${id}-help">${helperText}</p>` : ""}
           </div>
         `;
       }

       function SupportContactForm() {
         return `
           <section class="support-card" aria-labelledby="support-title">
             <p class="eyebrow">Support</p>
             <h1 id="support-title">How can we help?</h1>
             <p class="intro">
               Share your contact details and our support team will follow up with the best next step.
             </p>
             <p class="required-note">
               Fields marked with <span class="required-marker" aria-hidden="true">*</span> are required.
             </p>
             <form class="contact-form" id="support-form" novalidate>
               ${FormField({
                 id: "full-name",
                 label: "Full name",
                 type: "text",
                 name: "fullName",
                 required: true,
                 autocomplete: "name"
               })}
               ${FormField({
                 id: "email",
                 label: "Email address",
                 type: "email",
                 name: "email",
                 required: true,
                 autocomplete: "email"
               })}
               ${FormField({
                 id: "phone",
                 label: "Phone number",
                 type: "tel",
                 name: "phone",
                 autocomplete: "tel",
                 inputMode: "tel",
                 helperText: "Use international format, for example +1 555 123 4567."
               })}
               <button class="submit-button" type="submit">Send support request</button>
               <p class="form-status" id="form-status" aria-live="polite"></p>
             </form>
           </section>
         `;
       }

       function clearError(input) {
         const error = document.getElementById(`${input.id}-error`);
         const helpId = input.getAttribute("data-help-id");

         input.removeAttribute("aria-invalid");
         if (helpId) {
           input.setAttribute("aria-describedby", helpId);
         } else {
           input.removeAttribute("aria-describedby");
         }

         if (error) {
           error.remove();
         }
       }

       function showError(input, message) {
         clearError(input);

         const error = document.createElement("p");
         error.className = "error-message";
         error.id = `${input.id}-error`;
         error.textContent = message;

         input.setAttribute("aria-invalid", "true");
         input.setAttribute(
           "aria-describedby",
           [input.getAttribute("data-help-id"), error.id].filter(Boolean).join(" ")
         );
         input.insertAdjacentElement("afterend", error);
       }

       function validateForm(form) {
         const fullName = form.elements.fullName;
         const email = form.elements.email;
         const invalidFields = [];

         if (!fullName.value.trim()) {
           showError(fullName, "Error: Enter your full name.");
           invalidFields.push(fullName);
         } else {
           clearError(fullName);
         }

         if (!email.value.trim()) {
           showError(email, "Error: Enter your email address.");
           invalidFields.push(email);
         } else if (!email.validity.valid) {
           showError(email, "Error: Enter a valid email address, like name@example.com.");
           invalidFields.push(email);
         } else {
           clearError(email);
         }

         return invalidFields;
       }

       function attachFormBehavior() {
         const form = document.getElementById("support-form");
         const status = document.getElementById("form-status");

         Array.from(form.elements).forEach((control) => {
           if (control.matches("input[aria-describedby]")) {
             control.setAttribute("data-help-id", control.getAttribute("aria-describedby"));
           }

           if (control.matches("input")) {
             control.addEventListener("input", () => {
               clearError(control);
               status.textContent = "";
             });
           }
         });

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           status.textContent = "";

           const invalidFields = validateForm(form);

           if (invalidFields.length > 0) {
             invalidFields[0].focus();
             return;
           }

           form.reset();
           status.textContent = "Thanks. Your support request is ready to send.";
         });
       }

       document.getElementById("app").innerHTML = SupportContactForm();
       attachFormBehavior();
     </script>
   </body>
 </html>

